// HasCampaign applies the HasEdge predicate on the "campaign" edge.
func HasCampaign() predicate.MassEmailRecipient {
	return predicate.MassEmailRecipient(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CampaignTable, CampaignColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCampaignWith applies the HasEdge predicate on the "campaign" edge with a given conditions (other predicates).
func HasCampaignWith(preds ...predicate.MassEmailCampaign) predicate.MassEmailRecipient {
	return predicate.MassEmailRecipient(func(s *sql.Selector) {
		step := newCampaignStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MassEmailRecipient) predicate.MassEmailRecipient {
	return predicate.MassEmailRecipient(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MassEmailRecipient) predicate.MassEmailRecipient {
	return predicate.MassEmailRecipient(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MassEmailRecipient) predicate.MassEmailRecipient {
	return predicate.MassEmailRecipient(sql.NotPredicates(p))
}
